// ===================== VELORA ENGINE (shared) =====================
const MONTH_NAMES = ['January','February','March','April','May','June','July','August','September','October','November','December'];
const str = v => String(v ?? '').trim();
const num = v => {
  if (typeof v === 'number') return Number.isFinite(v) ? v : NaN;
  const s = str(v).replace(/[$,%\s]/g, '');
  if (s === '') return NaN;
  const n = Number(s);
  return Number.isFinite(n) ? n : NaN;
};
const norm = s => str(s).toLowerCase().replace(/[^a-z0-9]/g, '');
const r2 = n => Math.round((n + Number.EPSILON) * 100) / 100;

function mkDate(y, m, d) {
  const dt = new Date(Date.UTC(y, m - 1, d));
  return dt.getUTCFullYear() === y && dt.getUTCMonth() === m - 1 && dt.getUTCDate() === d ? dt : null;
}
function parseDate(v) {
  if (v instanceof Date) return Number.isNaN(v.getTime()) ? null : v;
  const s = str(v);
  if (!s) return null;
  let m = s.match(/^(\d{4})[-/](\d{1,2})[-/](\d{1,2})/);
  if (m) return mkDate(+m[1], +m[2], +m[3]);
  m = s.match(/^(\d{1,2})[-/](\d{1,2})[-/](\d{4}|\d{2})(?!\d)/);
  if (m) {
    let y = +m[3];
    if (y < 100) y += y >= 70 ? 1900 : 2000;
    // US month/day/year; if that is impossible (day > 12 in month slot) try day/month
    return mkDate(y, +m[1], +m[2]) || mkDate(y, +m[2], +m[1]);
  }
  if (/^\d{5}$/.test(s)) return new Date(Date.UTC(1899, 11, 30) + Number(s) * 86400000); // Sheets serial
  return null;
}
const iso = d => d.toISOString().slice(0, 10);

// ---------- 1. CLEANING ----------
function cleanData(raw) {
  const report = { rawRows: raw.length, duplicatesRemoved: 0, invalidRowsDropped: 0, missingNumbersSetToZero: 0, datesStandardised: 'Order Date and Ship Date converted to YYYY-MM-DD' };
  const seen = new Set();
  const rows = [];
  for (const r of raw) {
    const o = {};
    for (const [k, v] of Object.entries(r)) o[str(k)] = typeof v === 'string' ? str(v).replace(/\s+/g, ' ') : v;
    const key = o['Row ID'] !== undefined && o['Row ID'] !== '' ? 'id:' + o['Row ID'] : JSON.stringify(o);
    if (seen.has(key)) { report.duplicatesRemoved++; continue; }
    seen.add(key);
    const od = parseDate(o['Order Date']);
    const sales = num(o['Sales']);
    if (!od || !Number.isFinite(sales)) { report.invalidRowsDropped++; continue; }
    const sd = parseDate(o['Ship Date']);
    o['Order Date'] = iso(od);
    o['Ship Date'] = sd ? iso(sd) : '';
    o.Sales = sales;
    for (const f of ['Profit', 'Quantity', 'Discount']) {
      const n = num(o[f]);
      if (!Number.isFinite(n)) report.missingNumbersSetToZero++;
      o[f] = Number.isFinite(n) ? n : 0;
    }
    o['Postal Code'] = str(o['Postal Code']);
    o.Year = od.getUTCFullYear();
    o.Quarter = 'Q' + (Math.floor(od.getUTCMonth() / 3) + 1);
    o.Month = MONTH_NAMES[od.getUTCMonth()];
    o.YearMonth = o.Year + '-' + String(od.getUTCMonth() + 1).padStart(2, '0');
    o['Ship Days'] = sd ? Math.round((sd - od) / 86400000) : null;
    o._monthNum = od.getUTCMonth() + 1;
    rows.push(o);
  }
  report.cleanRows = rows.length;
  return { rows, report };
}

// ---------- 2. FIELD / METRIC RESOLUTION ----------
const FIELD_ALIASES = { product: 'Product Name', customer: 'Customer Name', date: 'Order Date', orderdate: 'Order Date', shipmode: 'Ship Mode', shippingmode: 'Ship Mode', subcategory: 'Sub-Category', zip: 'Postal Code', zipcode: 'Postal Code', shippingdays: 'Ship Days', month: 'Month', year: 'Year' };
const TIME_DIMS = new Set(['Year', 'Quarter', 'Month', 'YearMonth', 'Order Date', 'Ship Date']);
const NUMERIC_COLS = new Set(['Sales', 'Profit', 'Quantity', 'Discount', 'Year', 'Ship Days', 'Row ID']);
const DATE_COLS = new Set(['Order Date', 'Ship Date']);

const METRIC_ALIASES = {
  sales: 'sales', revenue: 'sales', totalsales: 'sales', turnover: 'sales',
  profit: 'profit', profits: 'profit', totalprofit: 'profit',
  quantity: 'quantity', units: 'quantity', qty: 'quantity', unitssold: 'quantity',
  orders: 'orders', ordercount: 'orders', distinctorders: 'orders',
  customers: 'customers', customercount: 'customers', distinctcustomers: 'customers',
  aov: 'aov', averageordervalue: 'aov', avgordervalue: 'aov',
  margin: 'margin', profitmargin: 'margin', profitmarginpct: 'margin', marginpct: 'margin',
  avgdiscount: 'avgDiscountPct', averagediscount: 'avgDiscountPct', discount: 'avgDiscountPct', avgdiscountpct: 'avgDiscountPct',
  profitperunit: 'profitPerUnit', rows: 'rows', transactions: 'rows', lines: 'rows',
  avgshipdays: 'avgShipDays', shippingdays: 'avgShipDays', avgshippingdays: 'avgShipDays',
  lossrows: 'lossRows', lossmakinglines: 'lossRows'
};
const normMetric = m => METRIC_ALIASES[norm(m)] || null;
const METRIC_LIST = ['sales', 'profit', 'quantity', 'orders', 'customers', 'aov', 'margin', 'avgDiscountPct', 'profitPerUnit', 'rows', 'avgShipDays', 'lossRows'];

function fieldMap(sample) {
  const m = {};
  for (const k of Object.keys(sample || {})) if (!k.startsWith('_')) m[norm(k)] = k;
  for (const [a, t] of Object.entries(FIELD_ALIASES)) if (m[norm(t)]) m[a] = m[norm(t)];
  return m;
}

function newAcc() { return { sales: 0, profit: 0, qty: 0, disc: 0, rows: 0, orders: new Set(), cust: new Set(), shipSum: 0, shipN: 0, loss: 0 }; }
function addAcc(a, r) {
  a.sales += r.Sales; a.profit += r.Profit; a.qty += r.Quantity; a.disc += r.Discount; a.rows++;
  if (r['Order ID']) a.orders.add(r['Order ID']);
  if (r['Customer ID']) a.cust.add(r['Customer ID']);
  if (r['Ship Days'] !== null && r['Ship Days'] !== undefined) { a.shipSum += r['Ship Days']; a.shipN++; }
  if (r.Profit < 0) a.loss++;
}
function finishAcc(a, discScale) {
  return {
    sales: r2(a.sales), profit: r2(a.profit), quantity: a.qty, orders: a.orders.size, customers: a.cust.size,
    aov: a.orders.size ? r2(a.sales / a.orders.size) : 0,
    margin: a.sales ? r2(a.profit / a.sales * 100) : 0,
    avgDiscountPct: a.rows ? r2(a.disc / a.rows * discScale) : 0,
    profitPerUnit: a.qty ? r2(a.profit / a.qty) : 0,
    rows: a.rows,
    avgShipDays: a.shipN ? r2(a.shipSum / a.shipN) : null,
    lossRows: a.loss
  };
}

// ---------- 3. QUERY EXECUTION ----------
function runQuery(rows, spec) {
  try {
    spec = (typeof spec === 'string') ? JSON.parse(spec) : (spec || {});
  } catch (e) {
    return { ok: false, error: 'query is not valid JSON: ' + e.message };
  }
  if (!rows.length) return { ok: false, error: 'No data rows available.' };
  const fmap = fieldMap(rows[0]);
  const validFields = Object.keys(rows[0]).filter(k => !k.startsWith('_'));
  const resolve = f => fmap[norm(f)] || null;
  const discScale = Math.max(...rows.map(r => r.Discount)) <= 1 ? 100 : 1;

  let data = rows;
  const applied = [];
  for (const f of (spec.filters || [])) {
    const col = resolve(f.field);
    if (!col) return { ok: false, error: `Unknown filter field "${f.field}".`, validFields };
    const op = norm(f.op || 'eq');
    const isNum = NUMERIC_COLS.has(col);
    const isDate = DATE_COLS.has(col);
    const cv = v => isDate ? (parseDate(v) ? iso(parseDate(v)) : str(v)) : isNum ? num(v) : str(v).toLowerCase();
    const val = f.value;
    let test;
    if (op === 'eq' || op === 'equals') test = x => cv(x) === cv(val);
    else if (op === 'neq' || op === 'ne' || op === 'not') test = x => cv(x) !== cv(val);
    else if (op === 'in') { const set = new Set([].concat(val).map(cv)); test = x => set.has(cv(x)); }
    else if (op === 'nin' || op === 'notin') { const set = new Set([].concat(val).map(cv)); test = x => !set.has(cv(x)); }
    else if (op === 'contains') test = x => str(x).toLowerCase().includes(str(val).toLowerCase());
    else if (op === 'gt') test = x => cv(x) > cv(val);
    else if (op === 'gte') test = x => cv(x) >= cv(val);
    else if (op === 'lt') test = x => cv(x) < cv(val);
    else if (op === 'lte') test = x => cv(x) <= cv(val);
    else if (op === 'between') { const [a, b] = [].concat(val); test = x => cv(x) >= cv(a) && cv(x) <= cv(b); }
    else return { ok: false, error: `Unknown filter op "${f.op}". Use eq, neq, in, nin, contains, gt, gte, lt, lte, between.` };
    data = data.filter(r => r[col] !== null && r[col] !== undefined && test(r[col]));
    applied.push(`${col} ${op} ${JSON.stringify(val)}`);
  }

  const metricsReq = (spec.metrics && spec.metrics.length ? [].concat(spec.metrics) : ['sales']).map(m => ({ raw: m, key: normMetric(m) }));
  const badMetric = metricsReq.find(m => !m.key);
  if (badMetric) return { ok: false, error: `Unknown metric "${badMetric.raw}".`, validMetrics: METRIC_LIST };
  const metricKeys = metricsReq.map(m => m.key);

  const dims = [];
  for (const g of [].concat(spec.groupBy || []).slice(0, 2)) {
    const col = resolve(g);
    if (!col) return { ok: false, error: `Unknown groupBy field "${g}".`, validFields };
    dims.push(col);
  }

  const total = newAcc();
  for (const r of data) addAcc(total, r);
  const totals = finishAcc(total, discScale);

  let groups = [];
  if (dims.length) {
    const map = new Map();
    for (const r of data) {
      const parts = dims.map(d => { const v = r[d]; return v === '' || v === null || v === undefined ? 'Unknown' : String(v); });
      const key = parts.join(' | ');
      if (!map.has(key)) map.set(key, { parts, sortParts: dims.map(d => d === 'Month' ? r._monthNum : r[d]), acc: newAcc() });
      addAcc(map.get(key).acc, r);
    }
    groups = [...map.entries()].map(([name, g]) => ({ name, parts: g.parts, _sort: g.sortParts, ...finishAcc(g.acc, discScale) }));

    for (const h of (spec.having || [])) {
      const mk = normMetric(h.metric);
      if (!mk) return { ok: false, error: `Unknown having metric "${h.metric}".`, validMetrics: METRIC_LIST };
      const op = norm(h.op), v = Number(h.value);
      groups = groups.filter(g => op === 'gt' ? g[mk] > v : op === 'gte' ? g[mk] >= v : op === 'lt' ? g[mk] < v : op === 'lte' ? g[mk] <= v : op === 'eq' ? g[mk] === v : true);
    }

    const timeFirst = TIME_DIMS.has(dims[0]);
    const sortKey = spec.sortBy ? normMetric(spec.sortBy) : null;
    if (spec.sortBy && !sortKey) return { ok: false, error: `Unknown sortBy metric "${spec.sortBy}".`, validMetrics: METRIC_LIST };
    if (timeFirst && !sortKey) {
      const dir = norm(spec.order) === 'desc' ? -1 : 1;
      groups.sort((a, b) => {
        for (let i = 0; i < a._sort.length; i++) {
          if (a._sort[i] < b._sort[i]) return -1 * dir;
          if (a._sort[i] > b._sort[i]) return 1 * dir;
        }
        return 0;
      });
    } else {
      const k = sortKey || metricKeys[0];
      const dir = norm(spec.order) === 'asc' ? 1 : -1;
      groups.sort((a, b) => ((a[k] ?? 0) - (b[k] ?? 0)) * dir);
    }
  }

  const groupCount = groups.length;
  const defLimit = dims.length && TIME_DIMS.has(dims[0]) ? 60 : 25;
  const limit = Math.min(Number(spec.limit) || defLimit, 200);
  groups = groups.slice(0, limit);

  // Return only the requested metrics (plus the sort metric) to keep the LLM context small.
  const keep = new Set([...metricKeys, ...(spec.sortBy && normMetric(spec.sortBy) ? [normMetric(spec.sortBy)] : [])]);
  groups = groups.map(g => {
    const o = { name: g.name, parts: g.parts };
    for (const k of METRIC_LIST) if (keep.has(k)) o[k] = g[k];
    return o;
  });

  return {
    ok: true,
    filtersApplied: applied,
    rowsMatched: data.length,
    totals,
    groupBy: dims,
    groupCount,
    returned: groups.length,
    groups,
    warning: data.length === 0 ? 'No rows matched the filters. Check exact values in the dataset profile.' : undefined
  };
}

// ---------- 4. DATASET PROFILE (given to the AI agent) ----------
function buildProfile(rows, report) {
  const acc = newAcc();
  for (const r of rows) addAcc(acc, r);
  const dates = rows.map(r => r['Order Date']).sort();
  const distinct = f => [...new Set(rows.map(r => r[f]).filter(v => v !== '' && v !== null && v !== undefined))];
  const small = {};
  for (const f of ['Category', 'Sub-Category', 'Region', 'Segment', 'Ship Mode', 'Year', 'Quarter', 'Country']) small[f] = distinct(f).sort();
  const maxDisc = Math.max(...rows.map(r => r.Discount));
  return {
    cleaning: report,
    columns: Object.keys(rows[0] || {}).filter(k => !k.startsWith('_')),
    derivedFields: ['Year', 'Quarter', 'Month', 'YearMonth', 'Ship Days'],
    orderDateRange: { from: dates[0], to: dates[dates.length - 1] },
    overall: finishAcc(acc, maxDisc <= 1 ? 100 : 1),
    discountScale: maxDisc <= 1 ? 'fraction (0.20 = 20%) - filter values use fractions; metric avgDiscountPct is already a percentage' : 'percentage points',
    exactValues: small,
    states: distinct('State').sort(),
    highCardinality: { products: distinct('Product Name').length, customers: distinct('Customer ID').length, cities: distinct('City').length }
  };
}
// =================== END VELORA ENGINE ===================

// ---- "clean data" node: clean the sheet and describe it for the AI agent ----
const raw = $input.all().map(i => i.json);
const { rows, report } = cleanData(raw);
return [{ json: buildProfile(rows, report) }];

// n8n Code node: "Build Dashboard" (v2, professional)
// Mode: Run Once for All Items | Language: JavaScript
const src = $('Get row(s) in sheet').all().map(i => i.json);

const pick = (r, names) => {
  const keys = Object.keys(r);
  for (const n of names) {
    const k = keys.find(k => k.toLowerCase().replace(/[^a-z]/g, '') === n);
    if (k !== undefined) return r[k];
  }
};
const toYM = (v) => {
  const s = String(v ?? '').trim();
  let m = s.match(/^(\d{4})-(\d{1,2})/);
  if (m) return m[1] + '-' + m[2].padStart(2, '0');
  m = s.match(/^(\d{1,2})[-\/](\d{1,2})[-\/](\d{2,4})/);
  if (m) return (m[3].length === 2 ? '20' + m[3] : m[3]) + '-' + m[1].padStart(2, '0');
  return 'Unknown';
};
const rows = src.map(r => {
  const m = toYM(pick(r, ['orderdate']));
  return {
    m, y: m.slice(0, 4),
    c: pick(r, ['category']) || 'Unknown',
    s: pick(r, ['subcategory']) || 'Unknown',
    r: pick(r, ['region']) || 'Unknown',
    g: pick(r, ['segment', 'customersegment']) || 'Unknown',
    p: pick(r, ['productname']) || 'Unknown',
    sa: Number(pick(r, ['sales', 'salesamount'])) || 0,
    pr: Number(pick(r, ['profit'])) || 0,
    q: Number(pick(r, ['quantity'])) || 0,
    d: Number(pick(r, ['discount'])) || 0,
  };
});
const payload = JSON.stringify(rows).replace(/</g, '\\u003c');

const html = `<!doctype html>
