<script>
var DATA = ${payload}, F = {y:'',r:'',c:'',g:'',s:''}, CH = {};
var css = getComputedStyle(document.documentElement);
var V = function(n){ return css.getPropertyValue(n).trim(); };
Chart.defaults.color = V('--muted'); Chart.defaults.font.family = 'system-ui,sans-serif';
var BLUE = V('--blue'), POS = V('--pos'), NEG = V('--neg');
var $ = function(id){ return document.getElementById(id); };
function money(n){ var a = Math.abs(n), s = a >= 1e6 ? (a/1e6).toFixed(2)+'M' : a >= 1e3 ? (a/1e3).toFixed(1)+'K' : a.toFixed(0); return (n < 0 ? '-$' : '$') + s; }
function esc(t){ return String(t).replace(/[&<>"]/g, function(c){ return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]; }); }
function agg(rows, k){ var m = {}; rows.forEach(function(r){ var key = typeof k === 'function' ? k(r) : r[k]; var o = m[key] || (m[key] = {sa:0,pr:0,q:0,n:0}); o.sa += r.sa; o.pr += r.pr; o.q += r.q; o.n++; }); return m; }
function sel(id, k){ var s = $(id); Array.from(new Set(DATA.map(function(d){ return d[k]; }))).sort().forEach(function(v){ var o = document.createElement('option'); o.value = v; o.textContent = v; s.appendChild(o); }); s.onchange = function(){ F[id === 'fy' ? 'y' : id === 'fr' ? 'r' : id === 'fc' ? 'c' : 'g'] = s.value; go(); }; }
function toggle(k, v, id){ F[k] = F[k] === v ? '' : v; if ($(id)) $(id).value = F[k]; go(); }
function filt(skipYear){ return DATA.filter(function(d){ return (skipYear || !F.y || d.y === F.y) && (!F.r || d.r === F.r) && (!F.c || d.c === F.c) && (!F.g || d.g === F.g) && (!F.s || d.s === F.s); }); }
